<?php
namespace App\Http\Controllers;
use App\Models\{Beneficiary,Family,AuditLog}; use Illuminate\Http\Request;
class BeneficiaryController extends Controller { private function data(Request $r):array{return $r->validate(['family_id'=>'required|exists:families,id','full_name'=>'required|string|max:255','national_id'=>'nullable|string|max:50','gender'=>'required|in:male,female','date_of_birth'=>'required|date|before_or_equal:today','relationship_to_head'=>'required|string|max:100','beneficiary_type'=>'required|in:child,adult,elderly,person_with_disability,caregiver,other','health_status'=>'nullable|string','disability_status'=>'boolean','education_status'=>'nullable|string','notes'=>'nullable|string']);} public function index(Request $r){$q=Beneficiary::with('family');if($s=$r->search)$q->where(fn($x)=>$x->where('beneficiary_number','ilike',"%$s%")->orWhere('full_name','ilike',"%$s%")->orWhere('national_id','ilike',"%$s%"));foreach(['gender','beneficiary_type','disability_status'] as $f)if($r->filled($f))$q->where($f,$r->$f);return view('beneficiaries.index',['beneficiaries'=>$q->latest()->paginate(15)->withQueryString()]);} public function create(){return view('beneficiaries.form',['beneficiary'=>new Beneficiary,'families'=>Family::orderBy('case_number')->get()]);} public function store(Request $r){$d=$this->data($r);$d['beneficiary_number']='BEN-'.now()->year.'-'.str_pad((string)(Beneficiary::withTrashed()->max('id')+1),4,'0',STR_PAD_LEFT);$d['created_by']=auth()->id();$b=Beneficiary::create($d);AuditLog::create(['user_id'=>auth()->id(),'action'=>'created','model_type'=>'Beneficiary','model_id'=>$b->id,'description'=>'Beneficiary created','new_values'=>$d,'ip_address'=>$r->ip()]);return redirect('/beneficiaries')->with('status','Beneficiary created.');} public function show(Beneficiary $beneficiary){return view('beneficiaries.show',['beneficiary'=>$beneficiary->load('family')]);} public function edit(Beneficiary $beneficiary){return view('beneficiaries.form',['beneficiary'=>$beneficiary,'families'=>Family::orderBy('case_number')->get()]);} public function update(Request $r,Beneficiary $beneficiary){$d=$this->data($r);$d['updated_by']=auth()->id();$beneficiary->update($d);AuditLog::create(['user_id'=>auth()->id(),'action'=>'updated','model_type'=>'Beneficiary','model_id'=>$beneficiary->id,'description'=>'Beneficiary updated','new_values'=>$d,'ip_address'=>$r->ip()]);return redirect('/beneficiaries')->with('status','Beneficiary updated.');} public function destroy(Beneficiary $beneficiary){abort_unless(auth()->user()->role==='admin',403);$beneficiary->delete();return back()->with('status','Beneficiary archived.');} }
